(function(){
  let particles = [];
  const N = 90;
  for(let i=0;i<N;i++){
    particles.push({
      a: Math.random()*Math.PI*2,
      r: 120 + Math.random()*380,
      speed: 0.0006 + Math.random()*0.0009,
      size: 1+Math.random()*2.5,
      hue: Math.floor(Math.random()*3),
      phase: Math.random()*Math.PI*2,
      driftSpeed: 0.3+Math.random()*0.6
    });
  }

  let waves = [];
  let waveTimer = 0;
  let last = performance.now();

  function hexToRgba(hex, alpha){
    const h = hex.replace('#','');
    const r = parseInt(h.substring(0,2),16);
    const g = parseInt(h.substring(2,4),16);
    const b = parseInt(h.substring(4,6),16);
    return 'rgba('+r+','+g+','+b+','+alpha+')';
  }

  function spawnWave(now){
    waves.push({born: now});
  }

  function loop(now){
    const dt = now-last; last = now;
    const w = W(), h = H();
    const cx = w*0.5, cy = h*0.5;

    ctx.clearRect(0,0,w,h);

    waveTimer += dt;
    if(waveTimer > 3200){ waveTimer = 0; spawnWave(now); }

    for(let i=waves.length-1;i>=0;i--){
      const wv = waves[i];
      const age = now - wv.born;
      const t = age/6000;
      if(t>1){ waves.splice(i,1); continue; }
      const rad = 40 + t*Math.min(w,h)*0.55;
      const alpha = (1-t)*0.22;
      ctx.beginPath();
      ctx.arc(cx,cy,rad,0,Math.PI*2);
      ctx.strokeStyle = hexToRgba(PALETTE[1], alpha);
      ctx.lineWidth = 1.4;
      ctx.stroke();
    }

    const glowR = Math.min(w,h)*0.28;
    const grad = ctx.createRadialGradient(cx,cy,0,cx,cy,glowR);
    grad.addColorStop(0, hexToRgba(PALETTE[2], DARK?0.16:0.22));
    grad.addColorStop(1, hexToRgba(PALETTE[2],0));
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(cx,cy,glowR,0,Math.PI*2);
    ctx.fill();

    const tSec = now/1000;
    for(const p of particles){
      p.a += p.speed*dt*0.06;
      const rr = p.r + Math.sin(tSec*p.driftSpeed + p.phase)*18;
      const x = cx + Math.cos(p.a)*rr;
      const y = cy + Math.sin(p.a)*rr*0.72;
      const flick = 0.5+0.5*Math.sin(tSec*1.3+p.phase*2);
      const col = PALETTE[p.hue % PALETTE.length];
      ctx.beginPath();
      ctx.fillStyle = hexToRgba(col, 0.35+0.4*flick);
      ctx.shadowBlur = 8;
      ctx.shadowColor = hexToRgba(col,0.6);
      ctx.arc(x,y,p.size*(0.7+0.5*flick),0,Math.PI*2);
      ctx.fill();
    }
    ctx.shadowBlur = 0;

    requestAnimationFrame(loop);
  }

  spawnWave(performance.now());
  requestAnimationFrame(loop);
})();
